(globalThis.TURBOPACK||(globalThis.TURBOPACK=[])).push(["object"==typeof document?document.currentScript:void 0,197482,t=>{"use strict";var e=t.i(843476),n=t.i(526527),o=t.i(682440);let i=[{type:"subtitle",contentRu:"1. Общие положения",contentEn:"1. GENERAL PROVISIONS",contentUk:"1. Загальні положення",level:1},{type:"paragraph",contentRu:"Настоящая политика направлена на предотвращение использования платформы {brandTosSite} для легализации доходов, полученных преступным путем, и финансирования терроризма. Мы обязуемся соблюдать высокие стандарты безопасности для защиты наших пользователей и обеспечения прозрачности всех операций по открытию игровых кейсов и обмену игровыми предметами.",contentEn:"This policy is aimed at preventing the use of the {brandTosSite} platform for the legalization of proceeds obtained by criminal means and the financing of terrorism. We commit to complying with high security standards to protect our users and ensure the transparency of all operations regarding the opening of game cases and the exchange of game items.",contentUk:"Ця політика спрямована на запобігання використанню платформи {brandTosSite} для легалізації (відмивання) доходів, одержаних злочинним шляхом, та фінансування тероризму. Ми зобов’язуємося дотримуватися високих стандартів безпеки для захисту наших користувачів і забезпечення прозорості всіх операцій із відкриття ігрових кейсів та обміну ігровими предметами."},{type:"subtitle",contentRu:"2. Принцип «Знай своего клиента» (KYC)",contentEn:'2. "KNOW YOUR CUSTOMER" (KYC) PRINCIPLE',contentUk:"2. Принцип «Знай свого клієнта» (KYC)",level:1},{type:"paragraph",contentRu:"Для обеспечения доступа к услугам сайта и возможности открытия игровых кейсов мы применяем процедуры идентификации пользователей.",contentEn:"To ensure access to the services of the site and the possibility of opening game cases, we apply user identification procedures.",contentUk:"Для забезпечення доступу до послуг сайту та можливості відкриття ігрових кейсів ми застосовуємо процедури ідентифікації користувачів."},{type:"list",contentRu:"",contentEn:"",contentUk:"",itemsRu:["Идентификация: Мы используем данные вашего профиля (например, через Steam API) для подтверждения личности пользователя.","Верификация: В случае обнаружения подозрительной активности мы оставляем за собой право запросить дополнительные документы для подтверждения вашей личности.","Связь данных: Информация, полученная в ходе идентификации, может быть связана с файлами cookie для обеспечения безопасности игровых сессий."],itemsEn:["Identification: We use your profile data (for example, through the Steam API) to confirm the identity of the user.","Verification: In the event of detecting suspicious activity, we reserve the right to request additional documents to confirm your identity.","Data link: Information obtained during identification may be linked to cookies to ensure the security of gaming sessions."],itemsUk:["Ідентифікація: Ми використовуємо дані вашого профілю (наприклад, через Steam API) для підтвердження особи користувача.","Верифікація: У разі виявлення підозрілої активності ми залишаємо за собою право запитати додаткові документи для підтвердження вашої особи.","Зв’язок даних: Інформація, отримана під час ідентифікації, може бути пов’язана з файлами cookie для забезпечення безпеки ігрових сесій."]},{type:"subtitle",contentRu:"3. Мониторинг транзакций",contentEn:"3. TRANSACTION MONITORING",contentUk:"3. Моніторинг транзакцій",level:1},{type:"paragraph",contentRu:"Мы осуществляем постоянный контроль за финансовыми операциями на платформе:",contentEn:"We carry out constant control over financial operations on the platform:",contentUk:"Ми здійснюємо постійний контроль за фінансовими операціями на платформі:"},{type:"list",contentRu:"",contentEn:"",contentUk:"",itemsRu:["Контроль платежей: Каждое пополнение баланса и использование промокодов проверяется на предмет легитимности.","Анализ активности: Мы используем технические решения для отслеживания необычных паттернов поведения при открытии игровых кейсов и выводе скинов.","Блокировка: При выявлении признаков мошенничества или отмывания средств, доступ к аккаунту и услугам сайта может быть временно ограничен до выяснения обстоятельств."],itemsEn:["Payment control: Every balance top-up and use of promo codes is checked for legitimacy.","Activity analysis: We use technical solutions to track unusual patterns of behavior when opening game cases and withdrawing skins.","Blocking: Upon identification of signs of fraud or money laundering, access to the account and site services may be temporarily restricted until circumstances are clarified."],itemsUk:["Контроль платежів: Кожне поповнення балансу та використання промокодів перевіряється на предмет легітимності.","Аналіз активності: Ми використовуємо технічні рішення для відстеження незвичних патернів поведінки під час відкриття ігрових кейсів та виведення скінів.","Блокування: У разі виявлення ознак шахрайства або відмивання коштів доступ до облікового запису та послуг сайту може бути тимчасово обмежений до з’ясування обставин."]},{type:"subtitle",contentRu:"4. Обязанности пользователя",contentEn:"4. USER OBLIGATIONS",contentUk:"4. Обов’язки користувача",level:1},{type:"list",contentRu:"",contentEn:"",contentUk:"",itemsRu:["Пользователь обязуется предоставлять достоверную информацию при использовании сервисов сайта.","Запрещается передавать данные своей сессии (временные ключи) третьим лицам.","Пользователь подтверждает, что средства, используемые для участия в игровом процессе, получены законным путем."],itemsEn:["The user undertakes to provide reliable information when using the services of the site.","It is prohibited to transfer your session data (temporary keys) to third parties.","The user confirms that the funds used to participate in the gameplay are obtained by legal means."],itemsUk:["Користувач зобов’язується надавати достовірну інформацію під час використання сервісів сайту.","Забороняється передавати дані своєї сесії (тимчасові ключі) третім особам.","Користувач підтверджує, що кошти, які використовуються для участі в ігровому процесі, отримані законним шляхом."]},{type:"subtitle",contentRu:"5. Меры безопасности и хранение данных",contentEn:"5. SECURITY MEASURES AND DATA STORAGE",contentUk:"5. Заходи безпеки та зберігання даних",level:1},{type:"paragraph",contentRu:"Все данные обрабатываются в соответствии с Политикой конфиденциальности и защищаются техническими средствами.",contentEn:"All data is processed in accordance with the Privacy Policy and is protected by technical means.",contentUk:"Усі дані обробляються відповідно до Політики конфіденційності та захищаються технічними засобами."},{type:"paragraph",contentRu:"Мы используем временные ключи сессий для защиты доступа к личным кабинетам пользователей.",contentEn:"We use temporary session keys to protect access to users' personal accounts.",contentUk:"Ми використовуємо тимчасові ключі сесій для захисту доступу до особистих кабінетів користувачів."},{type:"subtitle",contentRu:"6. Отказ в обслуживании",contentEn:"6. REFUSAL OF SERVICE",contentUk:"6. Відмова в обслуговуванні",level:1},{type:"paragraph",contentRu:"Компания оставляет за собой право отказать в предоставлении услуг или ограничить доступ к контенту сайта, если действия пользователя нарушают установленные правила безопасности или если пользователь отказывается проходить процедуру верификации.",contentEn:"The Company reserves the right to refuse the provision of services or restrict access to site content if the user's actions violate established security rules or if the user refuses to undergo the verification procedure.",contentUk:"Компанія залишає за собою право відмовити в наданні послуг або обмежити доступ до контенту сайту, якщо дії користувача порушують встановлені правила безпеки або якщо користувач відмовляється проходити процедуру верифікації."},{type:"subtitle",contentRu:"7. Контактная информация",contentEn:"7. CONTACT INFORMATION",contentUk:"7. Контактна інформація",level:1},{type:"paragraph",contentRu:"По всем вопросам, связанным с процедурами AML/KYC, подозрительной активностью или безопасностью вашего аккаунта, вы можете обратиться в службу поддержки: Email: {brandSupportEmail}",contentEn:"For all questions related to AML/KYC procedures, suspicious activity, or the security of your account, you can contact support: Email: {brandSupportEmail}.",contentUk:"З усіх питань, пов’язаних із процедурами AML/KYC, підозрілою активністю або безпекою вашого облікового запису, ви можете звернутися до служби підтримки: Email: {brandSupportEmail}"}],a="Anti-Money Laundering (AML) Policy and KYC Procedure — {brandTosSite}",c={ru:{backButton:"Вернуться",pageTitle:"Политика по борьбе с отмыванием денег (AML) и процедура KYC — {brandTosSite}"},en:{backButton:"Go back",pageTitle:a},ka:{backButton:"უკან დაბრუნება",pageTitle:a},kk:{backButton:"Артқа қайту",pageTitle:a},uz:{backButton:"Orqaga qaytish",pageTitle:a},ro:{backButton:"Înapoi",pageTitle:a},hu:{backButton:"Vissza",pageTitle:a},tr:{backButton:"Geri dön",pageTitle:a},pl:{backButton:"Wróć",pageTitle:a},mn:{backButton:"Буцах",pageTitle:a},pt:{backButton:"Voltar",pageTitle:a},uk:{backButton:"Повернутися",pageTitle:"Політика протидії відмиванню коштів (AML) та процедура KYC — {brandTosSite}"}};t.s(["default",0,function(){let{locale:t}=(0,n.useLocale)(),a=c[t];return(0,e.jsx)(o.z,{title:a.pageTitle,backButton:a.backButton,data:i})}],197482)}]);

